-- 1 Oct 2026 - Real hero pictures (generated by Re) for the directions, negation
-- and causative posts, replacing pictures that did not match the topic
-- (korean-nightmarket.jpg, korean-mistakes.jpg, korean-education.jpg).
-- Data-only and idempotent: guarded by slug and by the old file name; a step
-- that finds nothing logs a WARNING and never raises. The new files ship in
-- public/assets/blog in the same commit.

create or replace function pg_temp.hero(p_slug text, p_old text, p_new text)
returns void language plpgsql as $f$
declare n1 int; n2 int;
begin
  update public.blog_posts set hero_image = replace(hero_image, p_old, p_new)
   where slug = p_slug and hero_image like '%' || p_old;
  get diagnostics n1 = row_count;
  update public.blog_posts set content = replace(content, p_old, p_new)
   where slug = p_slug and content like '%' || p_old || '%';
  get diagnostics n2 = row_count;
  if n1 + n2 = 0 then raise warning 'hero nothing changed: % / %', p_slug, p_old; end if;
end $f$;

select pg_temp.hero('korean-directions-location-vocabulary', 'korean-nightmarket.jpg', 'korean-directions.jpg');
select pg_temp.hero('korean-directions-location-vocabulary-ar', 'korean-nightmarket.jpg', 'korean-directions.jpg');
select pg_temp.hero('korean-negation-grammar-guide', 'korean-mistakes.jpg', 'korean-negation.jpg');
select pg_temp.hero('korean-negation-grammar-guide-ar', 'korean-mistakes.jpg', 'korean-negation.jpg');
select pg_temp.hero('korean-causative-verbs-grammar', 'korean-education.jpg', 'korean-causative.jpg');
